// License policy checker
// Generated by create-vetwo-pack license-check plugin
// ESM imports (Prompt 25 fix): the package is "type": "module", so legacy
// require() calls crashed with "require is not defined in ES module scope".
import { execSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const policyPath = path.join(process.cwd(), "license-policy.json");
if (!fs.existsSync(policyPath)) {
  console.error("license-policy.json not found. Run from the package root.");
  process.exit(1);
}
const policy = JSON.parse(fs.readFileSync(policyPath, "utf-8"));
const allowlist = new Set(policy.allow || []);

let output;
try {
  output = execSync("npx license-checker --json --start .", {
    encoding: "utf-8",
    cwd: process.cwd(),
  });
} catch (e) {
  output = (e.stdout || "").toString();
}

const violations = [];
let entries = {};
try {
  entries = JSON.parse(output);
} catch (e) {
  console.error("Could not parse license-checker output.");
  process.exit(1);
}

for (const [pkg, info] of Object.entries(entries)) {
  const types = Array.isArray(info.licenses) ? info.licenses : [info.licenses];
  for (const t of types) {
    const normalized = String(t).trim();
    if (normalized === "UNKNOWN" && policy.failOnUnknown) {
      violations.push(pkg + ": unknown license");
    } else if (!allowlist.has(normalized)) {
      violations.push(pkg + ": " + normalized);
    }
  }
}

if (violations.length > 0) {
  console.error("License policy violations:");
  for (const v of violations) console.error("  - " + v);
  process.exit(1);
}
console.log("All dependency licenses comply with the license policy.");
